# query_types, extraction_methods, metric_types, output_filters


def gen_hist(samples):
    min_s = np.min(samples)
    max_s = np.max(samples)

    n_bins = 200 # This number influences the absolute result significantly.
    bins = np.linspace(min_s, max_s, n_bins)
    hist, bin_edges = np.histogram(samples, bins=bins, density=True)

    bins = []
    for i in range(len(bin_edges) - 1):
        bins.append((bin_edges[i] + bin_edges[i+1]) / 2)

    return bins, hist


